"use client";

import { useState } from "react";
import QRCode from "qrcode";
import config from "../config.json";

export default function QRPage() {
  const [qrURL, setQrURL] = useState("");

  const generarQR = async () => {
    try {
      const urlEvento = `${window.location.origin}${config.urlUpload}`;
      const dataURL = await QRCode.toDataURL(urlEvento);
      setQrURL(dataURL);
    } catch (err) {
      console.error("Error generando QR:", err);
      alert("Error generando QR");
    }
  };

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        fontFamily: "sans-serif",
        padding: "20px",
        background: "#f5f5f5",
      }}
    >
      <h1 style={{ fontSize: "2rem", marginBottom: "20px" }}>
        Generar QR para invitados
      </h1>

      <button
        onClick={generarQR}
        style={{
          padding: "12px 25px",
          fontSize: "1rem",
          background: "#0070f3",
          color: "white",
          border: "none",
          borderRadius: "8px",
          cursor: "pointer",
        }}
      >
        Generar QR
      </button>

      {qrURL && (
        <div
          style={{
            marginTop: "30px",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}
        >
          <img
            src={qrURL}
            alt="QR Code"
            style={{ width: "300px", height: "300px", marginBottom: "15px" }}
          />
          <a
            href={qrURL}
            download="QR_Evento.png"
            style={{
              padding: "10px 20px",
              background: "#28a745",
              color: "white",
              borderRadius: "5px",
              textDecoration: "none",
              fontWeight: "bold",
            }}
          >
            Descargar QR
          </a>
        </div>
      )}
    </div>
  );
}
